// TH15 v1.00b Stage 4 中Boss 非符 1 (st04mbs.ecl.txt MBoss1)
// source: st04mbs.ecl.txt:38-58; deps: MBoss1_at 60-98, MBoss1_at2 100-131,
//         MCir01 201-235, MCir01_at 243-284, MCir01_at2 286-324, MCir01b 326-359
// 源起点=MBoss公共timerReset(源0)，MBoss1在源40进入；观测源帧≈卡帧-124。

const TIME_LIMIT: int = 1924;   // 120 外壳缓冲 + 源1800时限 + 4 启动余量
const OPENING_BUFFER: int = 120;

// TH15 type 11 = talisman；见 transcribe/th15/touhou-bullets.ecl
const TH15_TALISMAN: int = 528;

const COLOR_A: int = 2;         // MCir01_at(2) / MCir01_at2(2)
const COLOR_B: int = 6;         // MCir01b: MCir01_at(6) / MCir01_at2(6)

// 0.05236 rad/frame = 3deg；0.261799 rad = 15deg；0.017453 rad = 1deg
const OMEGA: int = 546;         // 3deg in BAM
const PHASE_STEP: int = 2731;   // 15deg in BAM
const SPIRAL_STEP: int = 182;   // 1deg in BAM
const MAX_HP_BOSS: int = 13000;

// ---------------------------------------------------------------- shell
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // MBoss公共入口：movePos(-192,-64) 后 movePosTime(100,4,0,128)
    _ = spawn_enemy(-192fx, -64fx, MAX_HP_BOSS, 0, 0, 0, boss);
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ---------------------------------------------------------------- boss
async sub boss() {
    set_invuln(65535);
    set_hitbox(20fx);   // setHitbox(40,40) 普通圆取第一值x0.5
    set_hurtbox(24fx);  // setHurtbox(48,48)
    move_to(100, 0fx, 128fx, EASE_QUAD_OUT);   // movePosTime(100, mode4)
    wait(100);                                 // 源 wait(40)+MBoss1 wait(60)

    var rank: int = global(GVAR_RANK);
    var count: int = 13;                 // diffI B=12 -> 13 bodies ($B-- 自减 judged old value)
    var phase_step: angle = PHASE_STEP as angle;
    var shot_wait: int = 5;
    var spd: fx = 3fx;                   // Easy 2.0 / Normal 2 / Hard 3 / Lunatic 3
    var gap: int = 0;                    // MCir01_at2 Easy/Normal 15, Hard 5, Lunatic 0
    if rank == 0 { count = 7; phase_step = 5461 as angle; shot_wait = 10; spd = 2fx; gap = 15; }
    else if rank == 1 { spd = 2fx; gap = 15; }
    else if rank == 2 { gap = 5; }

    loop {
        mb_wave(count, phase_step, shot_wait, spd, OMEGA as angle,
                SPIRAL_STEP as angle, gap, 1);      // MBoss1_at: F0 递减
        wait(20);
        mb_move_rand();
        mb_move_wait(190);
        mb_wave(count, phase_step, shot_wait, spd, (-546) as angle,
                (-182) as angle, gap, -1);            // MBoss1_at2: F0 递增
        wait(20);
        mb_move_rand();
        mb_move_wait(190);
    }
}

// 一次 MBoss1_at / MBoss1_at2：创建 count 个 MCir01/MCir01b
sub mb_wave(count: int, phase_step: angle, shot_wait: int, spd: fx,
            omega: angle, spiral: angle, gap: int, dir: int) {
    var i0: int = 180;
    var f0: angle = 0deg;
    var a: int = -1;
    var n: int = 0;
    loop {
        a = a + 1;
        if a % 4 == 0 {
            _ = spawn_enemy($self_x, $self_y, 600, 0, 1000, 0,
                            circle(COLOR_B, omega, f0, spiral, i0, spd, gap));
        } else {
            _ = spawn_enemy($self_x, $self_y, 300, 0, 1000, 0,
                            circle(COLOR_A, omega, f0, spiral, i0, spd, gap));
        }
        i0 = i0 - 5;
        if dir > 0 { f0 = f0 - phase_step; } else { f0 = f0 + phase_step; }
        wait(shot_wait);
        n = n + 1;
        if n >= count { break; }
    }
}

// ---------------------------------------------------------------- moveRand
// moveRand(60,4,1.0)，limit (0,128,280,64): 内区 x±70, y112..144; 实际界 x±140, y96..160
sub mb_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub mb_begin_dir(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    mb_arm_next_step();
}

sub mb_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // 原生 ±pi/2 护栏 (0.05 rad)
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    mb_begin_dir(a as angle);
}

sub mb_move_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        mb_arm_next_step();
    }
}

// ---------------------------------------------------------------- child enemy
// MCir01 / MCir01b 存活路径：圆上生长，120帧后放开体碰，exit_wait 后切线离场并切换发弹。
// 第一轮发弹并入主任务；第二轮按源 async 的首跑延迟用 wait(11) 对齐。
async sub circle(color: int, omega: angle, phase: angle, spiral: angle,
                 exit_wait: int, speed: fx, gap: int) {
    set_hitbox(8fx);    // setHitbox(16,16)
    set_hurtbox(12fx);  // setHurtbox(24,24)
    set_enemy_flag(ENEMY_NO_BODY, 1);   // flagSet(15) 的 0x2 位

    var cx: fx = $self_x;
    var cy: fx = $self_y;
    var theta: angle = phase;
    var px: fx = cx;   // 上一帧位置，用于源 FINAL_ANGLE（本帧合成位移方向）
    var py: fx = cy;
    var move_ang: angle = 0deg;
    var t: int = 0;
    var b: angle = 0deg;          // MCir01_at 的 %B，从0起
    var total: int = 120 + exit_wait;

    while t < total {
        theta = theta + omega;
        var r: fx = 100fx;
        if t < 120 { r = 100fx * (t as fx) / 120fx; }   // moveCircleTime(120,0,r->100)
        var nx: fx = cx + r * cos(theta);
        var ny: fx = cy + r * sin(theta);
        move_ang = atan2(ny - py, nx - px);
        move_to(0, nx, ny, EASE_LINEAR);
        px = nx;
        py = ny;
        if t == 120 { set_enemy_flag(ENEMY_NO_BODY, 0); }
        // MCir01_at: wait(10) + 每4帧1发，角度 FINAL_ANGLE+B
        if t >= 11 && (t - 11) % 4 == 0 {
            var a: angle = move_ang + b;
            _ = fire(TH15_TALISMAN, color,
                     $self_x - (speed * 4fx) * cos(a),
                     $self_y - (speed * 4fx) * sin(a),
                     speed, a, none, none);
            b = b + spiral;
        }
        t = t + 1;
        wait(1);
    }

    var leave: angle = move_ang;
    move_vel(0, leave, 3fx, EASE_LINEAR);
    wait(11);
    if spiral > 0bam { b = 60deg; } else { b = -60deg; }   // B = F3 * 60
    var c: int = 0;
    while c < 101 {                 // $C=100 -> 101 cycles
        var d: int = 0;
        while d < 8 {               // $D=7 -> 8 shots
            var a2: angle = leave + b;
            _ = fire(TH15_TALISMAN, color,
                     $self_x - 8fx * cos(a2),
                     $self_y - 8fx * sin(a2),
                     2fx, a2, none, none);
            b = b + spiral;
            wait(5);
            d = d + 1;
        }
        wait(gap);
        c = c + 1;
    }
    loop { wait(1); }
}
